#!/usr/bin/env bash
# Prints the Homebrew formula (damast-dev/homebrew-tap, Formula/mast.rb) for a mast release.
#   formula.sh <version> <SHA256SUMS> [base-url]
# base-url defaults to the GitHub release; release.yml passes file://… to test-install unpublished builds.
set -euo pipefail
version=$1 sums=$2
base=${3:-https://github.com/damast-dev/mast/releases/download/v$version}

sha() { awk -v f="mast-$version-$1.tar.gz" '$2 == f || $2 == "*" f { print $1 }' "$sums" | grep -E '^[0-9a-f]{64}$'; }
mac_arm=$(sha aarch64-apple-darwin)
mac_intel=$(sha x86_64-apple-darwin)
linux_arm=$(sha aarch64-unknown-linux-musl)
linux_intel=$(sha x86_64-unknown-linux-musl)

cat <<EOF
# Generated by .github/scripts/formula.sh in damast-dev/mast on every release. Don't edit by hand.
class Mast < Formula
  desc "Command-line client for Damast and Forgejo, a drop-in for fj"
  homepage "https://github.com/damast-dev/mast"
  version "$version"
  license any_of: ["Apache-2.0", "MIT"]

  on_macos do
    on_arm do
      url "$base/mast-$version-aarch64-apple-darwin.tar.gz"
      sha256 "$mac_arm"
    end
    on_intel do
      url "$base/mast-$version-x86_64-apple-darwin.tar.gz"
      sha256 "$mac_intel"
    end
  end

  on_linux do
    on_arm do
      url "$base/mast-$version-aarch64-unknown-linux-musl.tar.gz"
      sha256 "$linux_arm"
    end
    on_intel do
      url "$base/mast-$version-x86_64-unknown-linux-musl.tar.gz"
      sha256 "$linux_intel"
    end
  end

  def install
    bin.install "mast"
  end

  test do
    assert_match "mast #{version.to_s.sub(/-mast\..*/, "")}", shell_output("#{bin}/mast --version")
  end
end
EOF
